using System.Reflection;
using System.Text.Json;
using Intropy.Topology;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>
/// The non-Aspire backend: the <c>check</c>, <c>graph</c>, and <c>generate</c> CLI verbs over a
/// discovered system. F5 (the Aspire backend) and these verbs consume the same discovered truth.
/// </summary>
public static class IntropyGenerate
{
    private static readonly JsonSerializerOptions s_json = new() { WriteIndented = true };

    /// <summary>Runs a generation CLI verb against the system discovered in <paramref name="assembly"/>.</summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line arguments; <c>args[0]</c> is the verb (check | graph | generate).</param>
    /// <returns>A process exit code.</returns>
    public static Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var verb = args.Length > 0 ? args[0] : "check";
        return Task.FromResult(verb switch
        {
            "check" => Check(assembly),
            "graph" => Graph(assembly),
            "generate" => Generate(assembly, args),
            _ => Unknown(verb),
        });
    }

    private static int Check(Assembly assembly)
    {
        try
        {
            var discovered = SystemDiscovery.Discover(assembly);
            Console.WriteLine($"ok: '{discovered.Topology.SystemName}' is valid ({discovered.Topology.Components.Count} components).");
            return 0;
        }
        catch (TopologyValidationException ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    private static int Graph(Assembly assembly)
    {
        var discovered = SystemDiscovery.Discover(assembly);
        Console.WriteLine(JsonSerializer.Serialize(DisplayModel(discovered.Topology), s_json));
        return 0;
    }

    /// <summary>
    /// The graph verb's human-facing projection of the model: camelCase, kebab-case kinds,
    /// short contract names, empty collections omitted. The wire format (plain model
    /// serialization) is unchanged — this is presentation, not interchange.
    /// </summary>
    private static Dictionary<string, object> DisplayModel(SystemTopology topology)
    {
        var model = new Dictionary<string, object>
        {
            ["systemName"] = topology.SystemName,
            ["components"] = topology.Components.Select(DisplayComponent).ToArray(),
            ["topics"] = topology.Topics.Select(t => new Dictionary<string, object>
            {
                ["pubsub"] = t.PubSubName,
                ["name"] = t.TopicName,
                ["contract"] = ShortTypeName(t.ContractTypeName),
            }).ToArray(),
        };

        if (topology.Connectors.Count > 0)
        {
            model["connectors"] = topology.Connectors.Select(c => new Dictionary<string, object>
            {
                ["name"] = c.Name,
                ["transport"] = c.Transport.DaprType,
                ["usedBy"] = c.UsedBy,
            }).ToArray();
        }

        if (topology.Services.Count > 0)
        {
            model["services"] = topology.Services.Select(s =>
            {
                var entry = new Dictionary<string, object> { ["name"] = s.Name };
                if (s.Service is ContainerService container)
                {
                    entry["image"] = container.Image;
                    entry["port"] = container.Port;
                }

                return entry;
            }).ToArray();
        }

        return model;
    }

    private static Dictionary<string, object> DisplayComponent(ComponentModel component)
    {
        var entry = new Dictionary<string, object>
        {
            ["name"] = component.Name,
            ["kind"] = KebabCase(component.Kind.ToString()),
        };

        if (component.Schedule is not null)
        {
            entry["schedule"] = component.Schedule;
        }

        if (component.Subscribes.Count > 0)
        {
            entry["subscribes"] = component.Subscribes
                .Select(t => new Dictionary<string, object> { ["pubsub"] = t.PubSubName, ["topic"] = t.TopicName })
                .ToArray();
        }

        if (component.Publishes.Count > 0)
        {
            entry["publishes"] = component.Publishes.Select(p =>
            {
                var edge = new Dictionary<string, object> { ["pubsub"] = p.PubSubName, ["topic"] = p.TopicName };
                if (p.Port != "default")
                {
                    edge["port"] = p.Port;
                }

                return edge;
            }).ToArray();
        }

        if (component.Connectors.Count > 0)
        {
            entry["connectors"] = component.Connectors
                .Select(c => new Dictionary<string, object>
                {
                    ["name"] = c.ConnectorName,
                    ["direction"] = c.Direction == ConnectorDirection.In ? "in" : "out",
                })
                .ToArray();
        }

        return entry;
    }

    private static string ShortTypeName(string fullName)
    {
        var index = fullName.LastIndexOfAny(['.', '+']);
        return index >= 0 ? fullName[(index + 1)..] : fullName;
    }

    private static string KebabCase(string pascal)
    {
        var builder = new System.Text.StringBuilder(pascal.Length + 4);
        foreach (var c in pascal)
        {
            if (char.IsUpper(c) && builder.Length > 0)
            {
                builder.Append('-');
            }

            builder.Append(char.ToLowerInvariant(c));
        }

        return builder.ToString();
    }

    private static int Generate(Assembly assembly, string[] args)
    {
        var directory = args.Skip(1).FirstOrDefault(a => !a.StartsWith('-')) ?? "./out";

        var discovered = SystemDiscovery.Discover(assembly);
        var artifacts = TopologyGenerator.Generate(discovered.Topology);
        artifacts.WriteTo(directory);

        Console.WriteLine($"generated {artifacts.Files.Count} files to '{directory}':");
        foreach (var file in artifacts.Files)
        {
            Console.WriteLine($"  {file.RelativePath}");
        }

        return 0;
    }

    private static int Unknown(string verb)
    {
        Console.Error.WriteLine($"unknown command '{verb}'. Expected: check | graph | generate.");
        return 2;
    }
}

using System.Net;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using Dapr.Client;
using Intropy.Contracts.IdempotencyService;
using Microsoft.Extensions.Options;

namespace Intropy.IdempotencyService.Client;

/// <summary>
/// Client for interacting with the Intropy Idempotency Service using Dapr service invocation.
/// </summary>
public class IdempotencyServiceClient(DaprClient daprClient, IOptions<IdempotencyServiceClientOptions>? options)
    : IIdempotencyServiceClient
{
    private readonly DaprClient _daprClient = daprClient ?? throw new ArgumentNullException(nameof(daprClient));
    private readonly string _appId = options?.Value.AppId ?? throw new ArgumentNullException(nameof(options));

    private static readonly JsonSerializerOptions JsonOptions = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        Converters = { new JsonStringEnumConverter() }
    };

    /// <inheritdoc/>
    public async Task<StatusResponse> GetStatusAsync(MessageInfo messageInfo,
        CancellationToken cancellationToken = new())
    {
        ArgumentNullException.ThrowIfNull(messageInfo);

        using var client = _daprClient.CreateInvokableHttpClient(_appId);
        var request = new HttpRequestMessage(HttpMethod.Post, "status");
        request.Content = JsonContent.Create(messageInfo, options: JsonOptions);

        try
        {
            var res = await client.SendAsync(request, cancellationToken);

            if (!res.IsSuccessStatusCode)
            {
                var details = await res.Content.ReadAsStringAsync(cancellationToken);
                throw new IdempotencyServiceException("Failed to get status", (int)res.StatusCode, details);
            }

            var obj = await JsonSerializer.DeserializeAsync<StatusResponse>(
                await res.Content.ReadAsStreamAsync(cancellationToken), cancellationToken: cancellationToken);

            if (obj is null)
                throw new IdempotencyServiceException("Failed to deserialize response", (int)res.StatusCode, null);
            return obj;
        }
        catch (Exception ex) when (ex.GetType().Name == "InvocationException")
        {
            throw new IdempotencyServiceException(
                "Failed to get status",
                500,
                ex.Message);
        }
        catch (Exception ex) when (ex.GetType().Name == "DaprException")
        {
            throw new IdempotencyServiceException("Dapr service invocation failed", ex);
        }
    }

    /// <inheritdoc/>
    public async Task CommitAsync(MessageInfo messageInfo,
        CancellationToken cancellationToken = new())
    {
        ArgumentNullException.ThrowIfNull(messageInfo);

        using var client = _daprClient.CreateInvokableHttpClient(_appId);
        var request = new HttpRequestMessage(HttpMethod.Post, "commit");
        request.Content = JsonContent.Create(messageInfo, options: JsonOptions);

        try
        {
            var response = await client.SendAsync(request, cancellationToken);
            if (!response.IsSuccessStatusCode)
            {
                var problemDetails = await response.Content.ReadAsStringAsync(cancellationToken);
                throw new IdempotencyServiceException(
                    $"Failed to commit: {response.StatusCode}",
                    (int)response.StatusCode,
                    problemDetails);
            }
        }
        catch (Exception ex) when (ex.GetType().Name == "InvocationException")
        {
            throw new IdempotencyServiceException(
                "Failed to commit",
                500,
                ex.Message);
        }
        catch (Exception ex) when (ex.GetType().Name == "DaprException")
        {
            throw new IdempotencyServiceException("Dapr service invocation failed", ex);
        }
    }


    public async Task<MessageInfo?> GetInfoAsync(string component, string id, CancellationToken cancellationToken)
    {
        if (string.IsNullOrWhiteSpace(component))
            throw new ArgumentException("Integration cannot be null or empty", nameof(component));
        if (string.IsNullOrWhiteSpace(id))
            throw new ArgumentException("Id cannot be null or empty", nameof(id));

        using var client = _daprClient.CreateInvokableHttpClient(_appId);
        var request = new HttpRequestMessage(HttpMethod.Get, $"components/{component}/{id}");

        try
        {
            var response = await client.SendAsync(request, cancellationToken);

            if (response.StatusCode == HttpStatusCode.NoContent)
                return null;

            if (!response.IsSuccessStatusCode)
            {
                var problemDetails = await response.Content.ReadAsStringAsync(cancellationToken);
                throw new IdempotencyServiceException(
                    $"Failed to get info: {response.StatusCode}",
                    (int)response.StatusCode,
                    problemDetails);
            }

            var content = await response.Content.ReadAsStringAsync(cancellationToken);
            return JsonSerializer.Deserialize<MessageInfo>(content, JsonOptions);
        }
        catch (Exception ex) when (ex.GetType().Name == "DaprException")
        {
            throw new IdempotencyServiceException("Dapr service invocation failed", ex);
        }
    }
}

using System.Net;
using System.Text.Json;
using CloudNative.CloudEvents;
using CloudNative.CloudEvents.Http;
using CloudNative.CloudEvents.SystemTextJson;
using Dapr;
using Dapr.Client;
using Intropy.Contracts.BusinessIncidentService;
using Microsoft.Extensions.Options;
using CloudEvent = CloudNative.CloudEvents.CloudEvent;

namespace Intropy.BusinessIncidentService.Client;

/// <summary>
/// Client for interacting with the Intropy Business Incident Service via Dapr service invocation.
/// Use it to trigger and resolve incidents (as CloudEvents) and to query incident state and history.
/// </summary>
/// <param name="daprClient">The Dapr client used for service invocation.</param>
/// <param name="options">Client configuration, including the target Dapr app id.</param>
public class BusinessIncidentServiceClient(
    DaprClient daprClient,
    IOptions<BusinessIncidentServiceClientOptions> options) : IBusinessIncidentServiceClient
{
    private readonly DaprClient _daprClient = daprClient ?? throw new ArgumentNullException(nameof(daprClient));
    private readonly string _appId = options.Value.AppId ?? throw new ArgumentNullException(nameof(options));

    private static readonly JsonEventFormatter JsonEventFormatter = new();

    /// <summary>
    /// Triggers a new business incident by sending a <c>Triggered</c> CloudEvent to the service.
    /// </summary>
    /// <param name="source">URI identifying the origin system (used as the CloudEvent <c>source</c>).</param>
    /// <param name="subject">Logical subject the incident relates to (e.g. an operation or resource name).</param>
    /// <param name="id">Unique CloudEvent id. Repeated calls with the same id are deduplicated by the service.</param>
    /// <param name="data">Incident payload, including the human-readable description.</param>
    /// <param name="batchId">Optional batch id used to group related incidents.</param>
    /// <exception cref="BusinessIncidentServiceException">The service returned an error response or could not be reached.</exception>
    public async Task Trigger(Uri source, string subject, string id, BusinessIncidentData data, string? batchId)
    {
        var cloudEvent = new CloudEvent
        {
            Source = source,
            Id = id,
            Subject = subject,
            Type = EventTypes.Triggered,
            DataContentType = "application/json",
            Data = data,
            Time = DateTimeOffset.UtcNow,
            ["batchid"] = batchId
        };

        await SendEvent(cloudEvent);
    }

    /// <summary>
    /// Retrieves a single incident by its id.
    /// </summary>
    /// <param name="id">The incident id.</param>
    /// <returns>The incident, or <c>null</c> if no incident with that id exists.</returns>
    /// <exception cref="BusinessIncidentServiceException">The service returned an error response or could not be reached.</exception>
    public async Task<IncidentResponse?> GetById(Guid id)
    {
        return await Invoke<IncidentResponse?>(HttpMethod.Get, $"incidents/{id}", allowNotFound: true);
    }

    /// <summary>
    /// Lists incidents matching the supplied filter, with optional pagination.
    /// </summary>
    /// <param name="filter">Optional filter and pagination parameters. When <c>null</c>, all incidents are returned using the service's default page size.</param>
    /// <returns>A paged list of incidents.</returns>
    /// <exception cref="BusinessIncidentServiceException">The service returned an error response or could not be reached.</exception>
    public async Task<IncidentListResponse> List(IncidentFilter? filter = null)
    {
        var query = BuildQuery(filter);
        var path = string.IsNullOrEmpty(query) ? "incidents" : $"incidents?{query}";
        return (await Invoke<IncidentListResponse>(HttpMethod.Get, path))!;
    }

    /// <summary>
    /// Retrieves the event history for an incident.
    /// </summary>
    /// <param name="id">The incident id.</param>
    /// <returns>The events recorded for the incident, in chronological order.</returns>
    /// <exception cref="BusinessIncidentServiceException">The service returned an error response or could not be reached.</exception>
    public async Task<List<IncidentEventResponse>> GetEvents(Guid id)
    {
        return (await Invoke<List<IncidentEventResponse>>(HttpMethod.Get, $"incidents/{id}/events"))!;
    }

    /// <summary>
    /// Manually marks an incident as resolved.
    /// </summary>
    /// <param name="id">The incident id.</param>
    /// <returns><c>true</c> if the incident was resolved; <c>false</c> if no incident with that id exists.</returns>
    /// <exception cref="BusinessIncidentServiceException">The service returned an error response or could not be reached.</exception>
    public async Task<bool> ResolveManual(Guid id)
    {
        var response = await InvokeRaw(HttpMethod.Post, $"incidents/{id}/resolve");
        return response.StatusCode != HttpStatusCode.NotFound;
    }

    /// <summary>
    /// Auto-resolves an incident by sending a <c>Resolved</c> CloudEvent to the service.
    /// </summary>
    /// <param name="source">URI identifying the origin system (used as the CloudEvent <c>source</c>).</param>
    /// <param name="subject">Logical subject the incident relates to. Must match the value used when triggering.</param>
    /// <param name="id">Unique CloudEvent id. Repeated calls with the same id are deduplicated by the service.</param>
    /// <param name="batchId">Optional batch id used to group related incidents.</param>
    /// <exception cref="BusinessIncidentServiceException">The service returned an error response or could not be reached.</exception>
    public async Task Resolve(Uri source, string subject, string id, string? batchId)
    {
        var cloudEvent = new CloudEvent
        {
            Source = source,
            Id = id,
            Subject = subject,
            Type = EventTypes.Resolved,
            DataContentType = "application/json",
            Data = new { },
            Time = DateTimeOffset.UtcNow,
            ["batchid"] = batchId
        };

        await SendEvent(cloudEvent);
    }

    private async Task<T?> Invoke<T>(HttpMethod method, string path, bool allowNotFound = false)
    {
        var response = await InvokeRaw(method, path);

        if (allowNotFound && response.StatusCode == HttpStatusCode.NotFound)
            return default;

        return await JsonSerializer.DeserializeAsync<T>(
            await response.Content.ReadAsStreamAsync());
    }

    private async Task<HttpResponseMessage> InvokeRaw(HttpMethod method, string path)
    {
        using var client = _daprClient.CreateInvokableHttpClient(_appId);
        var request = new HttpRequestMessage(method, path);

        try
        {
            var response = await client.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                var problemDetails = await response.Content.ReadAsStringAsync();
                throw new BusinessIncidentServiceException(
                    "Failed to call the business incident service",
                    (int)response.StatusCode,
                    problemDetails,
                    null);
            }

            return response;
        }
        catch (InvocationException ie)
        {
            throw new BusinessIncidentServiceException(
                "Failed to call the business incident service",
                500, ie.Message, ie);
        }
        catch (DaprException de)
        {
            throw new BusinessIncidentServiceException("Failed to communicate with dapr", de);
        }
        catch (Exception ex)
        {
            throw new BusinessIncidentServiceException("Unknown exception", ex);
        }
    }

    private static string BuildQuery(IncidentFilter? filter)
    {
        if (filter is null) return "";

        var parts = new List<string>();
        if (!string.IsNullOrEmpty(filter.Source)) parts.Add($"source={Uri.EscapeDataString(filter.Source)}");
        if (!string.IsNullOrEmpty(filter.Status)) parts.Add($"status={Uri.EscapeDataString(filter.Status)}");
        if (filter.Page.HasValue) parts.Add($"page={filter.Page.Value}");
        if (filter.PageSize.HasValue) parts.Add($"page_size={filter.PageSize.Value}");
        return string.Join("&", parts);
    }

    private async Task SendEvent(CloudEvent cloudEvent)
    {
        using var client = _daprClient.CreateInvokableHttpClient(_appId);
        var content = cloudEvent.ToHttpContent(ContentMode.Structured, JsonEventFormatter);

        var request = new HttpRequestMessage(HttpMethod.Post, "events");
        request.Content = content;

        try
        {
            var response = await client.SendAsync(request);

            if (!response.IsSuccessStatusCode)
            {
                var problemDetails = await response.Content.ReadAsStringAsync();
                throw new BusinessIncidentServiceException(
                    "Failed to call the business incident service",
                    (int)response.StatusCode,
                    problemDetails,
                    null);
            }
        }
        catch (InvocationException ie)
        {
            throw new BusinessIncidentServiceException(
                "Failed to call the business incident service",
                500,
                ie.Message,
                ie);
        }
        catch (DaprException de)
        {
            throw new BusinessIncidentServiceException("Failed to communicate with dapr", de);
        }
        catch (Exception ex)
        {
            throw new BusinessIncidentServiceException("Unknown exception", ex);
        }
    }
}

using System.Diagnostics;
using System.Text.Json;
using CloudNative.CloudEvents;
using CloudNative.CloudEvents.SystemTextJson;
using Dapr.Client;
using Intropy.BusinessIncidentService.Configuration;
using Intropy.BusinessIncidentService.Database;
using Intropy.BusinessIncidentService.Filters;
using Intropy.BusinessIncidentService.Models;
using Intropy.BusinessIncidentService.Utils;
using Intropy.Contracts.BusinessIncidentService;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Options;

namespace Intropy.BusinessIncidentService.Endpoints;

public static class EventEndpoints
{
    private static readonly CloudEventAttribute BatchIdAttribute =
        CloudEventAttribute.CreateExtension("batchid", CloudEventAttributeType.String);

    private static readonly JsonEventFormatter Formatter = new();

    public static IEndpointRouteBuilder MapEventEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapPost("/events",
                async (CloudEvent cloudEvent,
                    [FromServices] DaprClient dapr,
                    [FromServices] IOptions<DaprComponentsConfig> daprConfig) =>
                {
                    var activity = Activity.Current;

                    if (cloudEvent.Type != EventTypes.Triggered && cloudEvent.Type != EventTypes.Resolved)
                        return Results.BadRequest($"Unsupported event type: {cloudEvent.Type}");

                    activity?.SetTag("cloudevent.type", cloudEvent.Type);
                    activity?.SetTag("cloudevent.source", cloudEvent.Source?.ToString());
                    activity?.SetTag("cloudevent.id", cloudEvent.Id);

                    var config = daprConfig.Value;

                    var bytes = Formatter.EncodeStructuredModeMessage(cloudEvent, out _);
                    await dapr.PublishByteEventAsync(config.InternalPubSubName, config.InternalTopicName, bytes,
                        "application/cloudevents+json");

                    return Results.Accepted();
                })
            .WithName("receiveEvent")
            .WithDisplayName("Receive CloudEvent")
            .Produces(202)
            .Produces<ProblemDetails>(400)
            .ExcludeFromDescription()
            .RequireHost($"*:{Ports.Internal}");

        endpoints.MapPost("/events/subscribe/triggered",
            async (CloudEvent cloudEvent,
                IncidentRepository repository,
                ILogger<Program> logger) =>
            {
                var rawSource = cloudEvent.Source?.ToString()
                               ?? throw new InvalidOperationException("CloudEvent source is required");

                var source = SourceParser.Parse(rawSource);

                if (cloudEvent.Data == null)
                    return Results.Problem(detail: "data payload is required for .triggered events", statusCode: 400);

                var data = ((JsonElement)cloudEvent.Data).Deserialize<BusinessIncidentData>()
                           ?? throw new InvalidOperationException("data deserialized to null");

                if (string.IsNullOrWhiteSpace(data.Description))
                    return Results.Problem(detail: "data.description is required", statusCode: 400);

                var command = new TriggeredCommand(
                    Source: source,
                    CeId: cloudEvent.Id!,
                    Subject: cloudEvent.Subject!,
                    Time: cloudEvent.Time!.Value,
                    BatchId: cloudEvent[BatchIdAttribute] as string,
                    Description: data.Description,
                    Context: data.Context);

                var (id, wasInserted) = await repository.UpsertTriggered(command);

                logger.LogInformation(
                    wasInserted
                        ? "Created incident {id} for {source}:{ceId}"
                        : "Retried incident {id} for {source}:{ceId}",
                    id, source, cloudEvent.Id);

                return Results.Ok();
            })
            .ExcludeFromDescription()
            .AddEndpointFilter<ExceptionFilter>()
            .RequireHost($"*:{Ports.Internal}");

        endpoints.MapPost("/events/subscribe/resolved",
            async (CloudEvent cloudEvent,
                IncidentRepository repository,
                ILogger<Program> logger) =>
            {
                var rawSource = cloudEvent.Source?.ToString()
                               ?? throw new InvalidOperationException("CloudEvent source is required");

                var command = new ResolvedCommand(
                    Source: SourceParser.Parse(rawSource),
                    CeId: cloudEvent.Id!,
                    Time: cloudEvent.Time!.Value);

                var resolved = await repository.ResolveAuto(command);

                if (!resolved)
                    logger.LogInformation(
                        "No open incident found for {source}:{ceId} — already resolved or never existed",
                        command.Source, cloudEvent.Id);

                return Results.Ok();
            })
            .ExcludeFromDescription()
            .AddEndpointFilter<ExceptionFilter>()
            .RequireHost($"*:{Ports.Internal}");

        return endpoints;
    }
}

using System.Text.Json;
