            .WithName("resolveIncident")
            .WithDisplayName("Resolve Incident")
            .Produces(200)
            .Produces<ProblemDetails>()
            .RequireHost($"*:{Ports.Public}");

        return endpoints;
    }

    private static IncidentResponse ToResponse(BusinessIncident i)
    {
